import { additionalWorkouts, applyWorkoutDetails } from './workout-programmes.mjs';
// Structured editorial material. Distances, loads and sessions are examples, not entry standards.
const make=(base,rows,kind)=>rows.map(([slug,title,level,summary,meta,blocks,extra={}])=>({path:base+slug+'/',parent:base,slug,title,level,summary,meta,blocks,kind,...extra}));
const work=(title,items)=>({title,items});
const para=(title,text)=>({title,text});
const workouts=make('/training/workouts/',[
 ['foundation-builder','Foundation builder','Beginner','Build repeatable movement and pack comfort.','30–45 min · easy effort · light pack',[work('Session',['Set up a secure pack and choose a level route.','Start with 5 minutes at an easy pace. Ruck for 20–30 minutes at a pace you can talk through.','Finish with 5 minutes at an easier pace. Record time, distance and load.']),para('Progress','Repeat the route until the effort is predictable. Increase duration or load, not both at the same time.')]],
 ['endurance-challenger','Endurance challenger','Intermediate','Build a longer steady effort with a planned refuel stop.','60–90 min · steady · familiar load',[work('Session',['Choose a route with an easy exit and a reliable water plan.','Set a pace you can sustain for the full session; check in halfway.','Practise the food and drink you expect to use on your next long event.']),para('Progress','Extend time gradually after a comfortable repeat. Keep the pack familiar rather than adding weight just because the route is longer.')]],
 ['strength-focus','Strength focus','Intermediate','Build strength for carrying a pack and climbing.','30–45 min · dumbbells or sandbag',[work('Session',['Warm up with unloaded hinges and step-ups.','Perform three controlled sets each of squat, hinge, step-up and carry, with rest between sets.','Finish with a short easy ruck if you can maintain good form.']),para('Progress','Increase the resistance only when all repetitions remain controlled. Stop before technique breaks down.')]],
 ['community-response','Shared carry challenge','Intermediate','Work as a crew to move a shared load safely.','45–60 min · shared sandbag · group',[work('Session',['Agree on distance, handover points and a weight all participants can handle safely.','Ruck a loop; switch the shared carry at each agreed checkpoint.','Use a buddy to check footing and keep everyone together.']),para('Review','Record how often the load changed hands, whether the plan fit the group and one improvement for next time.')]],
 ['speed-and-agility','Pace changes','Intermediate','Practise controlled changes in pace without losing form.','35–45 min · light pack or unloaded',[work('Session',['Warm up for 10 minutes.','Alternate 2 minutes of brisk effort and 2 minutes of easier movement, four to six times.','Cool down and record the pace for each effort.']),para('Progress','Keep the load light and choose a clear surface. Do not use a heavy pack to practise sprinting.')]],
 ['recovery-flow','Recovery flow','Beginner','Make the next hard session possible.','20–30 min · unloaded or light pack',[work('Session',['Move easily for 15–20 minutes on a comfortable surface.','Spend a few minutes on comfortable ankle, hip and shoulder movement.','Check feet, pack fit and how you feel before planning the next effort.']),para('Progress','This session is not a test. Keep it manageable and use rest instead if you need it.')]],
 ['urban-ruck','Urban ruck','Intermediate','Practise steady pace through a varied urban route.','45–75 min · city paths · familiar load',[work('Session',['Plan a legal route with safe crossings and optional stairs.','Record moving time separately from stops.','Choose one climb or stair section to repeat next time.']),para('Progress','Use the same route to compare effort and pace. Change the route or load gradually.')]],
 ['hill-repeats','Hill repeats','Intermediate','Build uphill endurance and controlled descents.','35–50 min · hills',[work('Session',['Warm up on level ground for 10 minutes.','Choose a short climb with a safe return. Repeat four to six times at a strong but controlled effort.','Recover on the descent; finish with easy movement.']),para('Progress','Add a repeat before increasing pack weight. Reduce the load if descending becomes uncomfortable.')]],
 ['nijmegen-distance','Back-to-back distance','Advanced','Prepare for repeated long days rather than a single maximum effort.','Two days · sustained effort',[work('Session',['Choose two routes within your established distance capacity.','Keep the first day controlled; practise food, water and foot care afterward.','On the second day, adjust pace and distance if recovery is poor.']),para('Progress','Build consecutive-day capacity before extending both days. Follow your event’s actual rules for pack weight and distance.')]],
 ['sandbag-murph','Sandbag circuit','Advanced','Combine running and controlled sandbag work.','30–45 min · sandbag',[work('Session',['Warm up unloaded.','Alternate short unloaded runs with manageable sets of sandbag squats, carries, and push-ups.','Work at a pace that leaves each lift controlled; take rest as needed.']),para('Scaling','Reduce repetitions or use a lighter bag. Do not combine heavy loaded running with unfamiliar lifts.')]],
 ['sandbag-4x4','Sandbag 4×4','Intermediate','Repeat a short mixed session and compare rounds.','Four rounds · adjustable load',[work('Session',['Select a light-to-moderate sandbag and a safe flat area.','Complete four rounds of four controlled squats, four hinges, four step-ups per side and a short carry.','Rest between rounds as needed and note how pace changes.']),para('Progress','Keep movement quality consistent across rounds. Increase load only after a repeatable session.')]],
 ['beatdown-pyramid','Work capacity pyramid','Advanced','A demanding mixed session with a clear stopping point.','25–40 min · bodyweight or light sandbag',[work('Session',['Warm up. Choose two or three familiar exercises.','Build rounds from 4 to 6 to 8 repetitions, then work back down to 6 and 4.','Use planned rest and finish with easy movement.']),para('Progress','Start with a smaller pyramid if needed. Stop when form degrades; total repetitions are not worth an injury.')]],
 ['team-challenge','Team pace challenge','Intermediate','Practise shared pacing and responsibility.','60 min · group',[work('Session',['Agree on a route, pace band, regroup points and a shorter exit.','Rotate who sets the pace on different sections.','Check that every participant finishes with the group or has an agreed alternative.']),para('Review','Ask what helped the group move consistently and who could take more responsibility next time.')]],
 ['night-ruck','After-dark ruck','Intermediate','Build confidence and preparation in reduced visibility.','45 min · known legal route · lights',[work('Session',['Choose a familiar route with safe crossings and good exit options.','Bring lights, reflective gear and clothing for conditions.','Keep the group visible and together; avoid unfamiliar terrain or unsafe shortcuts.']),para('Review','Note where lighting, surface or visibility slowed the session and plan a safer alternative.')]]
],'Workout');
const exercises=make('/training/strength/',[
 ['push-up','Push-up','Beginner','Build controlled upper-body strength.','Bodyweight · chest and arms',[work('How to do it',['Start with hands on a stable surface or floor and a straight comfortable body position.','Lower under control, then press back up without letting hips sag.','Use an incline to scale difficulty.']),para('Common mistake','Chasing a prescribed depth when control is lost. Use a manageable range and follow specific test rules when practising a formal assessment.')]],
 ['pull-up','Pull-up','Intermediate','Develop pulling strength.','Pull-up bar · back and arms',[work('How to do it',['Use a secure bar and a comfortable grip.','Pull yourself up without swinging; lower under control.','Use assistance if needed and rest between sets.']),para('Progress','Reduce assistance gradually; use the required grip and range for your chosen test.')]],
 ['squat','Squat','Beginner','Build leg strength for repeated climbs and load handling.','Bodyweight or weight',[work('How to do it',['Stand with feet comfortably apart.','Bend hips and knees, keeping balance through the feet.','Stand back up smoothly.']),para('Progress','Increase resistance only when the range and control are consistent.')]],
 ['deadlift','Deadlift','Intermediate','Practise lifting a load from the ground.','Barbell, dumbbell or sandbag',[work('How to do it',['Start with an appropriate light load close to your body.','Hinge at the hips, keep the load close and brace comfortably.','Stand up, then lower the load under control.']),para('Progress','Learn the movement with a manageable load before testing strength. Seek coaching for unfamiliar heavy lifts.')]],
 ['step-up','Step-up','Beginner','Train climbing strength and single-leg balance.','Stable step or box',[work('How to do it',['Use a low, stable step.','Place your whole foot on the step and stand up under control.','Step back down gently and alternate sides.']),para('Progress','Increase height or add load only if control is maintained.')]],
 ['split-squat','Split squat','Intermediate','Build strength one leg at a time.','Bodyweight or dumbbells',[work('How to do it',['Stand in a stable staggered stance.','Lower as far as comfortable with control, then return upright.','Repeat on both sides.']),para('Progress','Use support for balance before increasing weight.')]],
 ['glute-bridge','Glute bridge','Beginner','Train hip extension with a simple floor exercise.','Floor or mat',[work('How to do it',['Lie on your back with knees bent and feet on the floor.','Lift your hips while keeping your back comfortable.','Lower slowly and repeat.']),para('Progress','Pause briefly at the top or increase resistance gradually.')]],
 ['calf-raise','Calf raise','Beginner','Build calf strength for climbing and longer distances.','Stable surface',[work('How to do it',['Stand with support within reach.','Rise onto the balls of your feet and lower slowly.','Keep balance and avoid bouncing.']),para('Progress','Use one leg or added resistance once double-leg repetitions are controlled.')]],
 ['farmer-carry','Farmer carry','Intermediate','Practise grip and controlled load carriage.','Two suitable weights',[work('How to do it',['Pick up manageable weights using a controlled lift.','Carry them over a clear, flat distance without rushing.','Set them down safely and rest.']),para('Progress','Increase time or load gradually; do not sacrifice grip or posture for speed.')]],
 ['plank','Plank','Beginner','Build endurance for maintaining trunk control.','Mat or floor',[work('How to do it',['Support yourself on forearms and toes or knees.','Hold a comfortable straight position while breathing normally.','End the hold before your hips sag or your back becomes uncomfortable.']),para('Progress','Use shorter repeated holds before attempting a longer maximum effort.')]],
 ['row','Row','Beginner','Develop pulling strength with a band or weight.','Resistance band or dumbbell',[work('How to do it',['Use a secure anchor or a supported stance.','Pull the resistance toward you without jerking or twisting.','Return slowly to the start.']),para('Progress','Add resistance gradually while maintaining comfortable shoulder movement.')]],
 ['lunge','Lunge','Intermediate','Build strength and coordination for uneven surfaces.','Bodyweight or light weights',[work('How to do it',['Step into a comfortable staggered position.','Lower under control and return to standing.','Alternate sides and keep the range manageable.']),para('Progress','Practise without weight before adding load.')]]
],'Exercise');
const articles=make('/resources/articles/',[
 ['why-shared-adversity-builds-teams','Why shared adversity builds teams','All','A difficult shared task can reveal how a group works.','Leadership · 4 min read',[para('Challenge with a purpose','There is a difference between putting people through a hard session and giving them a difficult task they can solve together. A meaningful ruck makes pace, route and load decisions visible. People discover who notices problems, who communicates clearly, and who needs support.'),para('Build trust through behaviour','Choose a challenge with clear expectations, roles and ways to adjust it. Encourage people to share the load when useful, not to prove they can suffer more than everyone else. Trust grows when people can rely on each other to show up, speak up and act responsibly.'),para('Review what happened','After the finish, talk about a real moment when the group had to adapt. Ask what worked, what did not, and what to change. The next shared session is a chance to put that change into practice. Avoid treating shared difficulty alone as proof of team cohesion.')]],
 ['fundamentals-of-rucking-form','Rucking form that holds up','All','Pay attention to fit, pace and movement under load.','Technique · 4 min read',[para('Start with the pack','A secure load that does not shift makes movement easier to manage. Adjust straps for comfort, keep dense objects close to your back, and check that nothing presses painfully into you. Try the setup on a shorter session first.'),para('Move naturally','Choose a stride that feels controlled on the terrain. Avoid forcing a long stride or an artificial posture. On hills, shorten your stride as needed and pay extra attention to footing on the way down.'),para('Check what changes','Compare the first and last parts of your route. If your movement changes significantly, slow down, shorten the session or reduce the load. Keep notes on pack fit, pace, discomfort and terrain, then change one variable on your next session.')]],
 ['nutrition-for-endurance','Fuel longer rucks','All','Prepare food, water and resupply before the event.','Endurance · 4 min read',[para('Plan for time outside','A longer event is not simply a shorter session repeated. Think about the expected time, weather, elevation and available stops. Carry enough water for the route and know where refills are possible; avoid assuming every water source is usable.'),para('Test your food','Choose foods you can tolerate while moving. Practise eating and drinking during manageable training sessions, rather than trying new products on event day. Plan a spare option and adapt to your own needs.'),para('Finish ready for the next session','After the ruck, drink and eat according to your needs, check your feet and change out of wet clothing. For multi-day events, plan recovery in advance. If you have specific dietary or health needs, seek individual advice.')]],
 ['mental-resilience','Keep working when it gets hard','All','Develop a repeatable approach to difficult sessions.','Mindset · 4 min read',[para('Break the work down','When a long route feels overwhelming, focus on the next meaningful checkpoint rather than the whole distance. Set a manageable rhythm and check whether your pace is sustainable.'),para('Distinguish effort from danger','Discomfort can be part of a demanding session, but pain, dizziness, confusion or deteriorating conditions deserve attention. Strength is not measured by ignoring a reason to stop. Choose in advance when you will adapt or turn around.'),para('Use the next session','Record one difficult moment and how you responded. Practice that skill again under manageable conditions. Progress is more useful than a dramatic story about one session.')]],
 ['competitive-rucking','Prepare for a demanding event','All','Work backwards from the event’s requirements.','Preparation · 5 min read',[para('Understand the task','Read the organiser’s current route, distance, time limits, mandatory equipment and load rules. A long distance event and a timed heavy pack event may demand different preparation. Do not assume that every event requires a weighted pack.'),para('Measure your starting point','Choose a repeatable session relevant to the event. Record terrain, load, time and effort. Use the result to identify what needs work: sustained pace, climbing, load comfort, strength or repeated days.'),para('Build and rehearse','Plan progressively harder sessions around enough recovery. Practise the actual equipment and food on a shorter rehearsal. Leave time to adjust before event day; avoid a last-minute jump in load or distance.')]],
 ['rucking-for-community','Build capability together','All','Make a crew more useful than a weekly workout group.','Community · 4 min read',[para('Create a dependable routine','Agree on a predictable meeting point and clear information for new participants. Invite people to choose a challenge they can complete safely while contributing to the group.'),para('Share responsibility','Rotate route planning, check-in, pace setting and the end-of-session review. Teach people how to make decisions together rather than depending on one leader for everything.'),para('Be useful outside the session','A reliable group can support volunteering and community initiatives when appropriately organised. Choose real needs and work with responsible organisations instead of assuming fitness alone qualifies someone for specialised tasks.')]],
 ['rucking-gear-guide','Choose gear that earns its place','All','Build a pack around the work and conditions.','Equipment · 4 min read',[para('Fit before features','Start with a pack that can hold your chosen load securely and fits comfortably. Check seams, straps and buckles. Use footwear that suits the surface and has been worn in training.'),para('Pack for the route','Bring water, weather-appropriate clothing, a light when needed and a way to navigate and contact help. Longer or remote outings may require additional equipment; plan around the actual conditions rather than a fixed list.'),para('Test the setup','Try changes on a short familiar route. Note pressure points, loose items and what you actually use. A simple dependable setup is often more useful than a complicated one you have not tested.')]]
],'Article');
const routes=make('/resources/routes/',[
 ['beginner-loop','Short loop','Beginner','A repeatable route with several exits.','Example: 5 km · modest elevation',[work('Plan',['Choose a local loop with safe surfaces and easy transport.','Mark the halfway point and at least one shorter alternative.','Record distance and time; repeat before changing load.']),para('Before leaving','Confirm the actual map, access, conditions and elevation. This is a route design, not a mapped trail.')]],
 ['ridge-line-challenge','Ridgeline challenge','Intermediate','Plan a route around a sustained climb.','Example: 12 km · 400 m ascent',[work('Plan',['Choose an appropriate marked route and check access.','Identify a clear high point, turnaround and return route.','Allow extra time for ascent and descent.']),para('Before leaving','Check local weather, daylight and footing. Adjust the planned distance and load for the actual route.')]],
 ['summit-ascent','Summit ascent','Advanced','Plan a demanding mountain outing without treating a target as a promise.','Example: 15 km · 1,200 m ascent',[work('Plan',['Select an established route suitable for your skills and the conditions.','Check the entire round trip, including descent and escape routes.','Set turnaround criteria based on weather, time, fatigue and access.']),para('Before leaving','Mountain travel requires appropriate preparation. Do not add a heavy pack simply to increase difficulty.')]],
 ['urban-loop','Urban endurance loop','Intermediate','Combine city paths, stairs and safe crossings.','Example: 8 km · mixed surfaces',[work('Plan',['Connect pedestrian paths, parks and one manageable climb.','Choose regroup points and transit alternatives.','Track moving and stopped time separately.']),para('Before leaving','Check current access and avoid private areas, unsafe crossings and busy roads.')]],
 ['multi-day-stage','Multi-day stage','Advanced','Plan repeatable distance and recovery over consecutive days.','Example: 20–25 km per day',[work('Plan',['Find accommodation or safe finish options before setting the distance.','Plan water, food and clothing for each stage.','Allow shorter alternatives if recovery is poor.']),para('Before leaving','Confirm distance, public access, accommodation and weather for the actual itinerary.')]],
 ['historic-route','Historic route','Intermediate','Make a local route around public historic sites.','Example: 10–15 km · adaptable',[work('Plan',['Identify public sites and connected legal paths.','Respect access restrictions and opening hours.','Include pauses for learning and safe regroup points.']),para('Before leaving','Check the map and access rules. Do not disturb historical sites or artefacts.')]]
],'Route template');
const fieldNotes=make('/resources/field-notes/',[
 ['first-snow-ruck','First snow ruck','All','Review how snow changes pace, footing and kit.','Practice scenario · cold weather',[para('Situation','Imagine the surface changes from firm trail to deeper snow halfway through a planned ruck. The group slows and people start to notice cold hands or feet.'),work('Review prompts',['What was the difference between planned and actual pace?','Which clothing or footwear adjustment helped?','At what point would you shorten the route or turn back?']),para('Next session','Choose a shorter familiar route and test one improvement. Do not treat a hypothetical example as a real weather report.')]],
 ['multi-day-distance','Multi-day distance review','All','Review recovery and repeatability over consecutive days.','Practice scenario · endurance',[para('Situation','A group is planning two consecutive long days. The second day begins with tired legs and sore feet.'),work('Review prompts',['Did the first day leave enough capacity for the second?','What food, rest and foot-care plan was useful?','Which part of the route or load could be adjusted?']),para('Next session','Keep the distance manageable and change only one part of the plan.')]],
 ['team-dynamics','Team communication under load','All','Examine how the group adapts as effort increases.','Practice scenario · group leadership',[para('Situation','A shared carry slows one part of the group, while the front begins to pull away.'),work('Review prompts',['Who noticed the gap?','Were the handover and regroup points clear?','Did the group support the person struggling without making decisions for them?']),para('Next session','Agree on a regroup signal and rotate pace setting. Review what happens next time.')]],
 ['equipment-check','When equipment fails','All','Use a small gear problem to improve preparation.','Practice scenario · equipment',[para('Situation','A strap begins to loosen during a long route. The load shifts and movement becomes less comfortable.'),work('Review prompts',['Was the equipment checked before departure?','Could the issue be fixed safely at a stop?','Was there a sensible exit if the repair failed?']),para('Next session','Inspect and repair equipment before using it again; test the change on a short route.')]]
],'Field-note exercise');
const events=make('/resources/events/',[
 ['nijmegen','Nijmegen Four Days Marches','Advanced','Four consecutive days of distance, pacing and recovery.','Netherlands · 30, 40 or 50 km per day',[para('What to prepare for','The organiser publishes several daily distance categories and eligibility rules. Plan for repeated days and check the category that applies to you.'),work('Before registering',['Read the current distance, age and entry rules.','Check whether your category has equipment requirements.','Plan accommodation, food and recovery between days.'])],{country:'NL',image:'progress-ruck.webp',links:[['Official distance rules','https://www.4daagse.nl/en/participate/civilian/distances'],['Official regulations','https://www.4daagse.nl/en/regulations']]}],
 ['mammutmarsch-stockholm','Mammutmarsch Stockholm','Advanced','A published 30 or 50 km endurance event.','Sweden · 17 April 2027 · 30/50 km',[para('What to prepare for','The organiser lists two distances for Stockholm. Read the route, registration and equipment requirements before deciding which distance suits you.'),work('Preparation',['Build time on your feet and rehearse food and footwear.','Check the course profile and transport options.','Confirm the date and availability with the organiser.'])],{country:'SE',image:'progress-ruck.webp',links:[['Official event page','https://mammutmarch.dk/events/mammutmarsch-stockholm']]}],
 ['mammutmarsch-copenhagen','Mammutmarsch Copenhagen','Advanced','Choose between published 30, 42 and 55 km distances.','Denmark · 1 May 2027 · 30/42/55 km',[para('What to prepare for','The organiser lists three distances. Check current event details and whether any pack requirements apply.'),work('Preparation',['Choose a distance that matches your training history.','Practise the planned footwear and nutrition.','Confirm access, registration and course rules before booking.'])],{country:'DK',image:'progress-ruck.webp',links:[['Official event page','https://mammutmarch.dk/events/mammutmarch-koebenhavn']]}]
],'Event');
workouts.push(...make("/training/workouts/",[["burpee-intervals","Burpee intervals","Intermediate","Practise a repeatable full-body effort without rushing technique.","20 min · bodyweight",[{"title":"Session","items":["Warm up with easy squats and presses against a wall.","Complete six 45-second work periods with 75 seconds of rest. Step back and forward for a lower-impact variation.","Count controlled repetitions, not rushed ones."]},{"title":"Progress and scaling","text":"Keep each round within your established capacity. Increase a round or improve technique before increasing speed."}]],["minute-by-minute","Minute-by-minute strength","Intermediate","A timed session to practise repeatable strength sets.","15 min · bodyweight or weights",[{"title":"Session","items":["Choose a familiar pulling or pressing movement.","Set a 12-minute timer. At the start of each minute, perform a small set you can repeat comfortably, then rest.","Stop the set before technique deteriorates."]},{"title":"Progress and scaling","text":"Record the repetitions and rest. Scale the movement or reduce the set if you cannot maintain the same quality."}]],["four-mile-ruck","Four-mile ruck with stations","Intermediate","Combine steady distance with short strength stops.","6.4 km example · familiar pack",[{"title":"How to approach it","items":["Choose a route with four safe stopping points.","Ruck at an even pace; at roughly each mile, stop for a brief set of squats or incline push-ups.","Keep time moving and stopped separate."]},{"title":"Progress and scaling","text":"Shorten the route or omit a station when needed. Use the same route to compare your effort on another day."}]],["partner-carry","Partner carry relay","Intermediate","Train handovers and controlled carrying with a partner.","20–30 min · manageable shared weight",[{"title":"Session","items":["Agree on a flat, clear route and short carry sections.","One person carries a manageable object while the other moves alongside. Stop to exchange it safely.","Rotate on agreed markers instead of waiting until someone is exhausted."]},{"title":"Progress and scaling","text":"Adjust the weight and duration independently. Record what made the handovers smooth."}]],["sandbag-strength-intervals","Sandbag strength intervals","Advanced","Combine controlled sandbag lifting with planned recovery.","30 min · sandbag",[{"title":"Session","items":["Warm up with unloaded movements and easy carries.","Alternate short sets of sandbag squats, supported rows and carries with deliberate rest.","Complete a controlled number of rounds that allows consistent technique."]},{"title":"Progress and scaling","text":"Use a load you already know how to handle. Set the bag down during breaks; do not chase a time at the expense of control."}]],["essential-basics","Essential strength circuit","Beginner","Learn a few repeatable movements that support rucking.","20–25 min · bodyweight or light weights",[{"title":"Session","items":["Choose a stable area with a bench or step.","Complete two or three manageable rounds of step-ups, incline push-ups and a short carry.","Rest between movements and finish with easy movement."]},{"title":"Progress and scaling","text":"Add repetitions or another round only after the current circuit feels repeatable."}]],["hill-team-rotation","Team hill rotation","Intermediate","Share a demanding climb while keeping the group together.","30–40 min · hills",[{"title":"Session","items":["Choose a short safe climb and agree on the descent route.","Rotate the person setting the pace each climb. Everyone works at a controlled effort.","Regroup at the top and bottom; take an agreed rest before repeating."]},{"title":"Progress and scaling","text":"Record the number of repeatable climbs. Do not require the same load or pace from everyone."}]],["sandbag-squat-press","Sandbag squat and press","Advanced","Build work capacity using familiar squat and press movements.","20 min · light-to-moderate sandbag",[{"title":"Session","items":["Warm up unloaded. Choose a familiar load and clear working space.","Alternate small controlled sets of squats and presses, resting as needed.","Stop before technique or overhead control declines."]},{"title":"Progress and scaling","text":"Scale to squats alone or a comfortable press variation. The session does not require continuous overhead holding."}]]],"Workout"));
exercises.push(...make("/training/strength/",[["overhead-press","Overhead press","Intermediate","Develop controlled shoulder and upper-body strength.","Dumbbells or light barbell",[{"title":"How to approach it","items":["Stand or sit with a comfortable stable stance.","Start with weights at shoulder height and press upward within a comfortable range.","Lower under control without forcing the back into an arch."]},{"title":"Progress and scaling","text":"Start light; use a shorter range or substitute an incline press if overhead movement is uncomfortable."}]],["dips","Dips","Intermediate","Practise controlled pressing strength.","Stable dip bars",[{"title":"How to approach it","items":["Use stable bars with an assisted setup if needed.","Support your body, bend the elbows within a comfortable range and keep the movement controlled.","Press back up without bouncing."]},{"title":"Progress and scaling","text":"Use incline push-ups as an alternative. Avoid forcing depth."}]],["bicep-curl","Biceps curl","Beginner","Build elbow-flexion strength for controlled handling.","Dumbbells or resistance band",[{"title":"How to approach it","items":["Stand or sit steadily with arms by your sides.","Curl the resistance while keeping the upper arms relatively still.","Lower slowly."]},{"title":"Progress and scaling","text":"Choose a lighter resistance rather than swinging the torso."}]],["tricep-extension","Triceps extension","Beginner","Practise elbow extension with a comfortable resistance.","Resistance band or cable",[{"title":"How to approach it","items":["Secure the band or use a cable.","Keep the elbows near your sides and extend them comfortably.","Return slowly without letting the resistance snap back."]},{"title":"Progress and scaling","text":"Increase resistance only if you can repeat the movement with control."}]],["lateral-raise","Lateral raise","Beginner","Strengthen the shoulders with controlled arm movement.","Light dumbbells",[{"title":"How to approach it","items":["Stand steadily with weights at your sides.","Raise the arms outward in a comfortable range, keeping the elbows slightly bent.","Lower slowly."]},{"title":"Progress and scaling","text":"Start light and do not force the arms above a comfortable height."}]],["face-pull","Face pull","Beginner","Build upper-back control.","Resistance band or cable",[{"title":"How to approach it","items":["Secure the resistance at a comfortable height.","Pull toward the face with controlled elbows and shoulders.","Return slowly while maintaining balance."]},{"title":"Progress and scaling","text":"Use an easy resistance and stable anchor; stop if the movement is uncomfortable."}]],["wall-sit","Wall sit","Beginner","Practise sustained lower-body effort.","Wall",[{"title":"How to approach it","items":["Stand with your back against a secure wall.","Slide down only to a comfortable height with feet stable.","Hold briefly while breathing normally, then stand."]},{"title":"Progress and scaling","text":"Increase hold time gradually or stay higher on the wall."}]],["kettlebell-swing","Kettlebell swing","Intermediate","Practise a controlled dynamic hip hinge.","Kettlebell",[{"title":"How to approach it","items":["Learn the hip hinge first with a light weight.","Use a clear space and a comfortable stance. Drive the movement from the hips rather than lifting with the arms.","Bring the weight back under control and stop before fatigue affects technique."]},{"title":"Progress and scaling","text":"Use deadlifts if unfamiliar with the movement; seek hands-on instruction before increasing speed or load."}]],["box-jump","Box jump","Intermediate","Develop controlled jumping and landing ability.","Low stable box",[{"title":"How to approach it","items":["Use a low, stable platform in a clear area.","Jump only to a height you can land on securely with both feet.","Step down and reset between attempts."]},{"title":"Progress and scaling","text":"Use step-ups as a lower-impact alternative. Do not increase height if landings are unstable."}]],["bulgarian-split-squat","Rear-foot-elevated split squat","Intermediate","Build single-leg strength and balance.","Low stable bench",[{"title":"How to approach it","items":["Place your rear foot on a low support and establish a comfortable stance.","Lower slowly while maintaining balance through the front foot.","Return under control and repeat on each side."]},{"title":"Progress and scaling","text":"Use a regular split squat or support for balance before adding load."}]]],"Exercise"));
articles.push(...make("/resources/articles/",[["community-programmes","Build a training programme for your crew","All","Make a shared programme repeatable, adaptable and worth returning to.","Leadership · training",[{"title":"Start with the people","text":"Agree on what the crew wants from its sessions: a demanding event, steady weekly distance, or building practical capacity together. Ask participants about constraints without requiring anyone to disclose private information. Design a route and workload with shorter options and regroup points."},{"title":"Build a rhythm","text":"Use a repeatable weekly structure. Keep a steady session predictable, add a planned challenge periodically, and give people time to recover. Record distance, time, load and how well the group stayed together. Share the plan before the next session."},{"title":"Learn from each session","items":["Ask what worked and what made the session harder than expected.","Change one part of the plan at a time.","Rotate responsibilities so more people can help organise and lead."]}]],["rucking-mindfulness","Find focus through rucking","All","Use a ruck as a deliberate break from distractions without turning it into another performance test.","Mindset · routine",[{"title":"Set a different goal","text":"Not every session needs to improve a time or distance. Choose a familiar route and a comfortable pace, leave the distractions aside when it is safe to do so, and notice your surroundings and effort. Keep enough attention on traffic, footing and conditions."},{"title":"Make it useful","text":"Some people find a predictable rhythm helpful for clearing their head. Others prefer conversation or a quiet shared ruck. Treat this as a practical routine, not a promise of a particular mental-health outcome."},{"title":"After the ruck","items":["Note what helped you stay present.","Keep the next session realistic rather than forcing a longer effort.","Use a demanding session when the goal calls for it, not because every outing must be hard."]}]],["family-rucking","Rucking with family and friends","All","Make a shared challenge fit the people who are taking part.","Community · inclusion",[{"title":"Choose the challenge together","text":"A family or mixed-experience group is not a selection event. Agree on an accessible route and a pace that keeps people together. Adults can choose their own load; children do not need a weighted pack to join in. Keep breaks, water and easy exits available."},{"title":"Build confidence without pressure","text":"Let each person decide what effort is right for them. Make shared responsibility part of the outing: route choices, checking the weather, food or regroup points. A short successful ruck can become the foundation for a more ambitious shared goal later."},{"title":"Make the next outing easier to organise","items":["Agree on a meeting point and realistic duration.","Invite feedback without comparing people’s performance.","Celebrate finishing together rather than carrying the same weight."]}]]],"Article"));
fieldNotes.push(...make("/resources/field-notes/",[["night-navigation","Night route review","All","Explore how visibility changes route choices.","Practice scenario · darkness",[{"title":"Situation","text":"A familiar route looks different after dark, and part of the group loses sight of the next junction."},{"title":"Review prompts","items":["Were lights and reflective equipment ready?","Did the group have a clear regroup plan?","What route change would make the next session easier to manage?"]}]],["long-stage-preparation","Long stage preparation","All","Review pacing, food and repeated days.","Practice scenario · distance",[{"title":"Situation","text":"An extended route takes longer than planned. The group reaches the intended break late and still has a long way to go."},{"title":"Review prompts","items":["Was the time estimate realistic?","What food, water or transport options were available?","What would trigger a shorter route next time?"]}]],["foot-care-review","Foot care review","All","Recognise a manageable problem before it becomes a reason to stop.","Practice scenario · footwear",[{"title":"Situation","text":"A participant notices rubbing early in a ruck. The next planned stop is some distance away."},{"title":"Review prompts","items":["What was the footwear and sock setup?","Could the group stop somewhere safe to address the rubbing?","How could the route or kit be adjusted next time?"]}]],["fatigue-and-pace","Fatigue and pace review","All","Look at changes in movement and effort over a session.","Practice scenario · pacing",[{"title":"Situation","text":"An initially manageable effort becomes harder later in a session and pack comfort declines."},{"title":"Review prompts","items":["Which changes in pace, terrain or load might explain the difference?","Did people have enough time to recover?","What would you change before repeating the route?"]}]]],"Field-note exercise"));
workouts.push(...make('/training/workouts/',additionalWorkouts,'Workout'));
applyWorkoutDetails(workouts);
for(const row of [...workouts,...exercises,...articles,...routes,...fieldNotes])row.image=row.kind==='Workout'?'train-forest.webp':row.kind==='Exercise'?'strength-park.webp':row.kind==='Article'?'learn-map.webp':row.kind==='Field-note exercise'?'lead-waterfront.webp':'progress-ruck.webp';
// Published route profiles: distance and ascent refer to the linked route, not a guarantee of conditions.
routes.push(...make('/resources/routes/',[
 ['sognsvann-loop','Sognsvann lakeside loop','Beginner','A short gravel route for repeatable pacing and load checks.','Oslo, Norway · 3.7 km · 17 m total ascent',[para('Route profile','The published route follows a gravel path around the lake. It is a loop with a low elevation gain. The profile is suitable for planning a short, repeatable ruck, subject to weather and access.'),work('Rucking application',['Use the same start and finish for repeatable measurements.','Record the actual route, elapsed time and pack load.','Check surface conditions and respect other users.']),para('Map and access','The linked UT.no route includes a map and elevation profile. It is a privately submitted route suggestion; confirm the actual path and conditions before departure.')],{country:'NO',image:'train-forest.webp',links:[['Published route, map and elevation profile','https://ut.no/turforslag/115076']]}],
 ['vettakollen-loop','Sognsvann–Vettakollen loop','Intermediate','A longer forest loop with a climb and a steeper descent.','Oslo, Norway · 8.7 km · 283 m total ascent',[para('Route profile','The published route climbs towards Vettakollen, descends south and returns towards Sognsvann past Båntjern. The source lists April–October as its suggested season.'),work('Rucking application',['Select a familiar load and allow time for the descent.','Review the route and establish a turnaround time.','Avoid increasing pack weight and ascent difficulty together.']),para('Map and access','UT.no notes that its route trace is approximate. Follow actual paths and markings; check the current conditions. The map and elevation profile are available at the link below.')],{country:'NO',image:'train-forest.webp',links:[['Published route, map and elevation profile','https://ut.no/turforslag/118737/sognsvann-vettakollen-sognsvann']]}]
],'Route profile'));
const articlePractice={
 'why-shared-adversity-builds-teams':['A practical crew exercise','Give a small group a shared route, a time window and one simple responsibility to rotate at each regroup point. Set an accessible alternative before starting. During the outing, observe whether people communicate changes, notice the back of the group and share the load fairly. Afterward, ask each person what helped them contribute. Challenge alone does not make a team; the way people respond to it matters.'],
 'fundamentals-of-rucking-form':['Run a repeatable pack-fit check','Choose a short familiar route. Before setting off, secure the load, adjust the straps and check that you can move without excessive shifting. Note your comfort halfway through and at the finish. If the pack rubs or changes your movement, adjust the setup or reduce the load. Repeat the route with the same load before deciding whether a change helped.'],
 'nutrition-for-endurance':['Rehearse the event plan','For a longer outing, identify reliable water refill points and decide when you can pause to eat. Bring food you already tolerate and a backup if the route takes longer. Log what you actually consumed and how comfortable it was. Use those observations for the next session instead of adopting a universal intake target. Check organiser rules on support stations and outside assistance.'],
 'mental-resilience':['Use a check-in rather than a slogan','Before the session, define what completion means and what would make you stop or adapt. At a regroup point, distinguish ordinary effort from a problem that needs action. If the plan remains appropriate, focus on the next manageable segment. If it does not, communicate the change and select the safer alternative. The review should capture what helped, not simply who endured the most discomfort.'],
 'competitive-rucking':['Work backwards from a real event','Write down the actual distance, pack requirements, surface, ascent, cut-off and support arrangements. Compare each with a recent repeatable session. Select one gap to address during the next training block. For a multi-day event, include consecutive manageable sessions rather than treating a single fast outing as proof of readiness. Recheck the organiser’s requirements and your progress before committing to harder work.'],
 'rucking-for-community':['A useful group session','Plan a route with public access, an agreed pace and an achievable shared task. Give one person responsibility for navigation, one for regrouping and one for checking the plan. Rotate these responsibilities on later outings. Avoid simulating emergency work that requires qualifications; build transferable habits such as communication, preparation and follow-through.'],
 'rucking-gear-guide':['Test equipment before buying more','Make a short checklist for pack security, footwear, clothing, visibility and water. Try the current setup on a familiar route, note a specific limitation, then change one item. A heavier or more expensive product is not automatically better. Keep essential safety equipment appropriate to the route, and do not test unfamiliar equipment for the first time at a demanding event.'],
 'community-programmes':['Build a four-week crew cycle','Set a consistent meeting time, publish distance and load options, and nominate a route lead and a sweep. Start with repeatable outings. Introduce a shared task or terrain change only after the group has demonstrated that the current plan works. Leave a lighter session for review. Keep participation voluntary and make shorter options normal rather than exceptional.'],
 'rucking-mindfulness':['Make space for observation','Choose a low-complexity route where attention to traffic and navigation is manageable. Notice your pace, breathing, posture and surroundings without turning the outing into a performance test. If you are with others, agree when you will talk and when you will move quietly. Record one observation afterward, rather than promising a particular mental-health outcome.'],
 'family-rucking':['Plan for different capacities','Choose a route around the least experienced participant and provide genuine exit options. Adults can choose their own familiar loads; children do not need added weight to participate. Let everyone contribute to decisions about pace and breaks. A shared outing should be repeatable, enjoyable and safe rather than an imposed endurance test.']
};
